import{_ as e,o as s,c as l,a2 as o}from"./chunks/framework.CAUU6m5Y.js";const h=JSON.parse('{"title":"Technology Choices & Exhaustive Comparisons","description":"","frontmatter":{},"headers":[],"relativePath":"04-tech-comparisons.md","filePath":"04-tech-comparisons.md"}'),a={name:"04-tech-comparisons.md"};function n(i,t,r,d,g,c){return s(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="technology-choices-exhaustive-comparisons" tabindex="-1">Technology Choices &amp; Exhaustive Comparisons <a class="header-anchor" href="#technology-choices-exhaustive-comparisons" aria-label="Permalink to &quot;Technology Choices &amp; Exhaustive Comparisons&quot;">​</a></h1><p>This document provides exhaustive comparisons across 8 major architectural categories, detailing the chosen technology versus all realistic industry alternatives.</p><hr><h2 id="_1-concurrency-control-atomic-sql-conditional-updates-vs-redis-lua-vs-pessimistic-select-for-update-vs-optimistic-locking-occ" tabindex="-1">1. Concurrency Control: Atomic SQL Conditional Updates vs Redis Lua vs Pessimistic SELECT FOR UPDATE vs Optimistic Locking (OCC) <a class="header-anchor" href="#_1-concurrency-control-atomic-sql-conditional-updates-vs-redis-lua-vs-pessimistic-select-for-update-vs-optimistic-locking-occ" aria-label="Permalink to &quot;1. Concurrency Control: Atomic SQL Conditional Updates vs Redis Lua vs Pessimistic SELECT FOR UPDATE vs Optimistic Locking (OCC)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Evaluation Factor</th><th style="text-align:left;">Atomic Conditional SQL [This Project]</th><th style="text-align:left;">Redis Lua Scripts</th><th style="text-align:left;">Postgres SELECT FOR UPDATE</th><th style="text-align:left;">Optimistic Concurrency (OCC)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Throughput (Contended Single SKU)</strong></td><td style="text-align:left;"><strong>8,000 - 15,000 RPS</strong></td><td style="text-align:left;">50,000+ RPS</td><td style="text-align:left;">500 - 1,200 RPS</td><td style="text-align:left;">Poor under high contention (&lt;500 RPS)</td></tr><tr><td style="text-align:left;"><strong>Oversell Guarantee</strong></td><td style="text-align:left;"><strong>100% Guaranteed by DB Kernel</strong></td><td style="text-align:left;">100% Guaranteed (Single Thread)</td><td style="text-align:left;">100% Guaranteed (Row Lock)</td><td style="text-align:left;">Guaranteed via version checks</td></tr><tr><td style="text-align:left;"><strong>Crash Durability</strong></td><td style="text-align:left;"><strong>Instant (ACID WAL)</strong></td><td style="text-align:left;">Asynchronous (AOF/RDB loss risk)</td><td style="text-align:left;">Instant (ACID WAL)</td><td style="text-align:left;">Instant (ACID WAL)</td></tr><tr><td style="text-align:left;"><strong>Deadlock Risk</strong></td><td style="text-align:left;"><strong>Zero (Single atomic statement)</strong></td><td style="text-align:left;">Zero</td><td style="text-align:left;">High (Multi-row locks)</td><td style="text-align:left;">Zero (Retry loop aborts)</td></tr><tr><td style="text-align:left;"><strong>Implementation Complexity</strong></td><td style="text-align:left;"><strong>Low</strong></td><td style="text-align:left;">Medium</td><td style="text-align:left;">Low</td><td style="text-align:left;">Medium</td></tr></tbody></table><ul><li><strong>Why I Used This</strong>: Atomic conditional updates (<code>UPDATE ... WHERE available &gt;= :q</code>) execute in a single SQL round-trip, leveraging Postgres row locks for microsecond durations while avoiding lock wait queues.</li><li><strong>Why I Did Not Use Alternatives</strong>: <ul><li><em>Redis Lua</em>: While faster in raw memory, Redis requires complex two-phase commit synchronization with Postgres. If Redis crashes before flushing to Postgres, reservation state is lost.</li><li><em>SELECT FOR UPDATE</em>: Holds row locks across multiple application round-trips, starving connection pools under 50,000 RPS.</li><li><em>Optimistic Concurrency Control (OCC)</em>: Under 90%+ contention, 95% of OCC threads fail version matching and enter expensive retry loops, consuming excessive CPU.</li></ul></li><li><strong>30-Second Spoken Answer</strong>: <blockquote><p>&quot;I chose atomic conditional SQL updates with database CHECK constraints because they guarantee zero overselling at the database engine level without holding open pessimistic lock queues. Unlike Redis alone, there is zero risk of cache drift or lost reservation state during crash recovery.&quot;</p></blockquote></li></ul><hr><h2 id="_2-web-framework-fastapi-python-3-13-vs-express-js-vs-spring-boot-vs-go-gin-vs-nestjs" tabindex="-1">2. Web Framework: FastAPI (Python 3.13) vs Express.js vs Spring Boot vs Go Gin vs NestJS <a class="header-anchor" href="#_2-web-framework-fastapi-python-3-13-vs-express-js-vs-spring-boot-vs-go-gin-vs-nestjs" aria-label="Permalink to &quot;2. Web Framework: FastAPI (Python 3.13) vs Express.js vs Spring Boot vs Go Gin vs NestJS&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Evaluation Factor</th><th style="text-align:left;">FastAPI [This Project]</th><th style="text-align:left;">Express.js (Node)</th><th style="text-align:left;">Spring Boot (Java)</th><th style="text-align:left;">Go Gin</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Async Performance</strong></td><td style="text-align:left;"><strong>High (uvloop ASGI)</strong></td><td style="text-align:left;">High (Node Event Loop)</td><td style="text-align:left;">Very High (Virtual Threads)</td><td style="text-align:left;">Ultra High (Goroutines)</td></tr><tr><td style="text-align:left;"><strong>Type Safety &amp; Schemas</strong></td><td style="text-align:left;"><strong>Pydantic v2 (Rust-backed)</strong></td><td style="text-align:left;">Manual / Joi / Zod</td><td style="text-align:left;">Static Strong Typing</td><td style="text-align:left;">Static Strong Typing</td></tr><tr><td style="text-align:left;"><strong>Auto OpenAPI Docs</strong></td><td style="text-align:left;"><strong>Built-in Interactive Swagger</strong></td><td style="text-align:left;">Manual Swagger configuration</td><td style="text-align:left;">Springfox / Springdoc</td><td style="text-align:left;">Manual Swagger</td></tr><tr><td style="text-align:left;"><strong>Developer Velocity</strong></td><td style="text-align:left;"><strong>Very High</strong></td><td style="text-align:left;">High</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Medium</td></tr></tbody></table><ul><li><strong>Why I Used This</strong>: FastAPI provides native Python async/await, automated Pydantic schema validation compiled in Rust, and instant Swagger API documentation.</li><li><strong>Why I Did Not Use Alternatives</strong>: <ul><li><em>Express.js</em>: Lacks native schema validation and automatic OpenAPI generation; requires callback/promise chaining wrappers for clean error propagation.</li><li><em>Go Gin</em>: High performance, but slower developer iteration time for complex state machine logic.</li></ul></li></ul><hr><h2 id="_3-database-layer-postgresql-16-async-sqlalchemy-vs-mongodb-vs-dynamodb-vs-mysql" tabindex="-1">3. Database Layer: PostgreSQL 16 + Async SQLAlchemy vs MongoDB vs DynamoDB vs MySQL <a class="header-anchor" href="#_3-database-layer-postgresql-16-async-sqlalchemy-vs-mongodb-vs-dynamodb-vs-mysql" aria-label="Permalink to &quot;3. Database Layer: PostgreSQL 16 + Async SQLAlchemy vs MongoDB vs DynamoDB vs MySQL&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Evaluation Factor</th><th style="text-align:left;">PostgreSQL 16 [This Project]</th><th style="text-align:left;">MongoDB</th><th style="text-align:left;">AWS DynamoDB</th><th style="text-align:left;">MySQL 8.0</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Data Integrity / CHECKs</strong></td><td style="text-align:left;"><strong>Strict Table CHECK Constraints</strong></td><td style="text-align:left;">Document validation rules</td><td style="text-align:left;">Condition expressions</td><td style="text-align:left;">Basic CHECK constraints</td></tr><tr><td style="text-align:left;"><strong>Isolation Guarantees</strong></td><td style="text-align:left;"><strong>Full ACID (Read Committed to Serializable)</strong></td><td style="text-align:left;">Multi-document ACID (High latency)</td><td style="text-align:left;">Eventual consistency default</td><td style="text-align:left;">Full ACID (InnoDB)</td></tr><tr><td style="text-align:left;"><strong>Connection Pooling</strong></td><td style="text-align:left;"><strong>Asyncpg connection pooling</strong></td><td style="text-align:left;">Mongoose driver pool</td><td style="text-align:left;">HTTP Request-based</td><td style="text-align:left;">aiomysql pool</td></tr></tbody></table><ul><li><strong>Why I Used This</strong>: Flash sales require absolute mathematical conservation invariants. PostgreSQL&#39;s check constraints (<code>CHECK (available + reserved + sold == total_allocated)</code>) guarantee that corrupted states are rejected by the database engine.</li></ul>',14)])])}const u=e(a,[["render",n]]);export{h as __pageData,u as default};
